#!/usr/bin/env node
/**
 * Generates the original sound-effect files that the game ships as real audio
 * assets.
 *
 * Why this exists: the brief asks for a sound effect for EVERY action, free of
 * any corporate/copyrighted audio, and explicitly forbids runtime Web-Audio-API
 * synthesis. Generated files are allowed ("generated AI is ok"). So the missing
 * effects are synthesised HERE, offline, and committed as ordinary .wav files
 * like every other asset. The game only ever plays files; `core/audio.js` still
 * contains no oscillator and no noise buffer.
 *
 * Every file this script writes is an original work generated by this script:
 * there is no third-party sample in any of them, so nothing here can violate a
 * licence. docs/AUDIO-CREDITS.md records them as "original, generated by
 * scripts/generate-sfx.mjs".
 *
 * Pure Node, no dependencies. Run from the repository root:
 *
 *   node scripts/generate-sfx.mjs
 */

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';

const ROOT = resolve(import.meta.dirname, '..');
const RATE = 44100;

// ---------------------------------------------------------------- primitives

function mono(seconds) {
  return new Float64Array(Math.max(1, Math.round(seconds * RATE)));
}

function mix(dst, src, gain = 1, offsetSec = 0) {
  const off = Math.round(offsetSec * RATE);
  for (let i = 0; i < src.length && off + i < dst.length; i++) dst[off + i] += src[i] * gain;
  return dst;
}

/** Deterministic pseudo-random, so re-running the script reproduces the files. */
function rng(seed) {
  let s = (seed >>> 0) || 1;
  return () => {
    s ^= s << 13;
    s ^= s >>> 17;
    s ^= s << 5;
    return ((s >>> 0) / 4294967296) * 2 - 1;
  };
}

function whiteNoise(seconds, seed) {
  const rand = rng(seed);
  const out = mono(seconds);
  for (let i = 0; i < out.length; i++) out[i] = rand();
  return out;
}

function envelope(sig, attackSec, decaySec, curve = 2) {
  const a = Math.max(1, Math.round(attackSec * RATE));
  const d = Math.max(1, Math.round(decaySec * RATE));
  for (let i = 0; i < sig.length; i++) {
    let e;
    if (i < a) e = i / a;
    else {
      const t = Math.min(1, (i - a) / d);
      e = Math.pow(1 - t, curve);
    }
    sig[i] *= e;
  }
  return sig;
}

/** One-pole lowpass. `cutoff` may be a number (Hz) or a per-sample function. */
function lowpass(sig, cutoff, q = 1) {
  let y = 0;
  for (let i = 0; i < sig.length; i++) {
    const fc = typeof cutoff === 'function' ? cutoff(i / sig.length) : cutoff;
    const a = 1 - Math.exp((-2 * Math.PI * Math.min(fc, RATE / 2 - 100)) / RATE / Math.max(0.25, q));
    y += a * (sig[i] - y);
    sig[i] = y;
  }
  return sig;
}

function highpass(sig, cutoff) {
  let y = 0;
  for (let i = 0; i < sig.length; i++) {
    const a = 1 - Math.exp((-2 * Math.PI * cutoff) / RATE);
    y += a * (sig[i] - y);
    sig[i] = sig[i] - y;
  }
  return sig;
}

function bandpass(sig, lo, hi) {
  return highpass(lowpass(sig, hi), lo);
}

function sine(seconds, freq, seedPhase = 0) {
  const out = mono(seconds);
  for (let i = 0; i < out.length; i++) {
    const t = i / RATE;
    const f = typeof freq === 'function' ? freq(t) : freq;
    out[i] = Math.sin(2 * Math.PI * f * t + seedPhase);
  }
  return out;
}

function thud(freqStart, freqEnd, seconds, curve = 3) {
  const sig = mono(seconds);
  for (let i = 0; i < sig.length; i++) {
    const t = i / sig.length;
    const f = freqStart + (freqEnd - freqStart) * t;
    sig[i] = Math.sin(2 * Math.PI * f * (i / RATE)) * Math.pow(1 - t, curve);
  }
  return sig;
}

function click(seed, seconds = 0.012, lo = 1800, hi = 5200) {
  const sig = envelope(whiteNoise(seconds, seed), 0.0008, seconds, 3);
  return bandpass(sig, lo, hi);
}

/** Wrap-crossfade a loop so the seam is inaudible when played with loop=true. */
function makeSeamless(sig, fadeSec = 0.25) {
  const fade = Math.round(fadeSec * RATE);
  const out = new Float64Array(sig.length);
  out.set(sig);
  for (let i = 0; i < fade; i++) {
    const t = i / fade;
    out[i] = sig[i] * t + sig[sig.length - fade + i] * (1 - t);
  }
  return out.subarray(0, sig.length - fade);
}

function normalize(sig, peak = 0.85) {
  let max = 0;
  for (const v of sig) max = Math.max(max, Math.abs(v));
  if (max > 0) {
    const g = peak / max;
    for (let i = 0; i < sig.length; i++) sig[i] *= g;
  }
  return sig;
}

function writeWav(relPath, sig, peak = 0.85) {
  normalize(sig, peak);
  const n = sig.length;
  const buf = Buffer.alloc(44 + n * 2);
  buf.write('RIFF', 0);
  buf.writeUInt32LE(36 + n * 2, 4);
  buf.write('WAVE', 8);
  buf.write('fmt ', 12);
  buf.writeUInt32LE(16, 16);
  buf.writeUInt16LE(1, 20); // PCM
  buf.writeUInt16LE(1, 22); // mono
  buf.writeUInt32LE(RATE, 24);
  buf.writeUInt32LE(RATE * 2, 28);
  buf.writeUInt16LE(2, 32);
  buf.writeUInt16LE(16, 34);
  buf.write('data', 36);
  buf.writeUInt32LE(n * 2, 40);
  for (let i = 0; i < n; i++) {
    const v = Math.max(-1, Math.min(1, sig[i]));
    buf.writeInt16LE(Math.round(v * 32767), 44 + i * 2);
  }
  const out = join(ROOT, relPath);
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, buf);
  console.log(`wrote ${relPath} (${(buf.length / 1024).toFixed(1)} kB, ${(n / RATE).toFixed(2)}s)`);
}

// ------------------------------------------------------------------ effects

// Brake: a pedal tap - hydraulic hiss, a faint pad squeak, and the body thud of
// the weight transferring forward.
{
  const sig = mono(0.42);
  const hiss = envelope(bandpass(whiteNoise(0.42, 11), 900, 5200), 0.012, 0.3, 2.2);
  mix(sig, hiss, 0.5);
  const squeak = envelope(sine(0.12, (t) => 1150 - 260 * t), 0.01, 0.1, 2);
  mix(sig, squeak, 0.22, 0.02);
  mix(sig, thud(95, 55, 0.3), 0.9, 0.0);
  writeWav('assets/audio/racing/brake.wav', sig, 0.8);
}

// Handbrake: the ratchet of the lever, then a tyre chirp as the rears lock and
// the car starts to slide.
{
  const sig = mono(0.72);
  for (let c = 0; c < 3; c++) mix(sig, click(31 + c * 7, 0.014, 1600, 5600), 0.85, 0.02 + c * 0.055);
  const chirp = envelope(bandpass(whiteNoise(0.5, 21), 650, 3200), 0.02, 0.42, 1.6);
  for (let i = 0; i < chirp.length; i++) chirp[i] *= 1 + 0.18 * Math.sin((2 * Math.PI * 32 * i) / RATE);
  mix(sig, chirp, 0.55, 0.16);
  mix(sig, thud(80, 50, 0.35), 0.8, 0.14);
  writeWav('assets/audio/racing/handbrake.wav', sig, 0.82);
}

// Gear change: the mechanical clunk of the lever and dog rings. Fills the
// 'gear-change' gap that was previously substituted with metal-click.
{
  const sig = mono(0.3);
  mix(sig, thud(170, 120, 0.12), 0.8, 0);
  mix(sig, thud(240, 190, 0.1), 0.5, 0.045);
  mix(sig, click(77, 0.01, 2400, 7000), 0.7, 0.0);
  mix(sig, click(78, 0.008, 3000, 8000), 0.5, 0.05);
  writeWav('assets/audio/racing/gear-change.wav', sig, 0.75);
}

// Pause: the world drops away - a descending air sweep with a soft latch.
{
  const sig = mono(0.55);
  const sweep = envelope(whiteNoise(0.55, 41), 0.02, 0.48, 1.8);
  lowpass(sweep, (t) => 2600 * Math.pow(1 - t, 1.7) + 220);
  mix(sig, sweep, 0.6);
  mix(sig, thud(120, 70, 0.22), 0.55, 0.0);
  mix(sig, click(42, 0.01, 2000, 4200), 0.45, 0.02);
  writeWav('assets/audio/ui/pause.wav', sig, 0.7);
}

// Resume: the world comes back - the same sweep rising, with the latch undone.
{
  const sig = mono(0.55);
  const sweep = envelope(whiteNoise(0.55, 51), 0.02, 0.48, 1.8);
  lowpass(sweep, (t) => 240 + 2800 * Math.pow(t, 1.6));
  mix(sig, sweep, 0.6);
  mix(sig, thud(75, 130, 0.22), 0.5, 0.02);
  mix(sig, click(52, 0.01, 2200, 4600), 0.45, 0.28);
  writeWav('assets/audio/ui/resume.wav', sig, 0.7);
}

// Exit game: a warm two-note farewell chime, original tones, no jingle DNA.
{
  const sig = mono(0.95);
  const a = envelope(sine(0.55, 392), 0.012, 0.5, 2); // G4
  const b = envelope(sine(0.7, 261.63), 0.015, 0.66, 2); // C4
  const shimmer = envelope(bandpass(whiteNoise(0.5, 61), 2200, 6500), 0.01, 0.45, 3);
  mix(sig, a, 0.5, 0);
  mix(sig, b, 0.55, 0.18);
  mix(sig, shimmer, 0.12, 0.02);
  writeWav('assets/audio/ui/exit.wav', sig, 0.72);
}

// Crowd cheer: the grandstand at the start and the finish. Swelling filtered
// noise with lively modulation - no sampled crowd, no third-party audio.
{
  const sig = mono(2.4);
  const bed = whiteNoise(2.4, 71);
  bandpass(bed, 420, 4200);
  for (let i = 0; i < bed.length; i++) {
    const t = i / bed.length;
    const swell = Math.min(1, t * 4) * (0.55 + 0.45 * Math.pow(1 - Math.max(0, t - 0.55) / 0.45, 1.4));
    const churn = 1 + 0.35 * Math.sin((2 * Math.PI * 3.2 * i) / RATE) + 0.22 * Math.sin((2 * Math.PI * 5.7 * i) / RATE + 1.2);
    bed[i] *= swell * churn * 0.5;
  }
  mix(sig, bed, 1);
  for (let v = 0; v < 7; v++) {
    const voice = envelope(bandpass(whiteNoise(0.45, 80 + v * 13), 700 + v * 120, 2600 + v * 200), 0.06, 0.38, 2);
    mix(sig, voice, 0.1, 0.12 + v * 0.21);
  }
  writeWav('assets/audio/scene/crowd-cheer.wav', sig, 0.85);
}

// City ambience: Anandapur street bed - low rumble, distant movement.
{
  const sig = makeSeamless(lowpass(whiteNoise(6, 91), 320), 0.4);
  for (let i = 0; i < sig.length; i++) {
    sig[i] *= 0.5 + 0.12 * Math.sin((2 * Math.PI * 0.11 * i) / RATE) + 0.08 * Math.sin((2 * Math.PI * 0.31 * i) / RATE + 2);
  }
  const far = envelope(bandpass(whiteNoise(1.2, 92), 180, 700), 0.35, 0.8, 1.6);
  mix(sig, far, 0.2, 1.1);
  writeWav('assets/audio/scene/city-ambience.wav', sig, 0.55);
}

// Home ambience: quiet room tone for the family scenes.
{
  const sig = makeSeamless(lowpass(whiteNoise(6, 101), 210), 0.4);
  for (let i = 0; i < sig.length; i++) sig[i] *= 0.55 + 0.1 * Math.sin((2 * Math.PI * 0.07 * i) / RATE);
  mix(sig, envelope(thud(140, 120, 0.18), 0.01, 0.16, 2.5), 0.06, 2.2);
  writeWav('assets/audio/scene/home-ambience.wav', sig, 0.45);
}

// Workshop ambience: floor tone with a slow fan hum and distant tool ticks.
{
  const sig = makeSeamless(mix(mix(lowpass(whiteNoise(6, 111), 520), sine(6, 72), 0.12), whiteNoise(6, 112), 0.06), 0.4);
  for (let i = 0; i < sig.length; i++) sig[i] *= 0.5 + 0.1 * Math.sin((2 * Math.PI * 0.13 * i) / RATE);
  for (let t = 0; t < 5; t++) mix(sig, click(120 + t, 0.012, 1200, 3800), 0.16, 0.7 + t * 1.05);
  writeWav('assets/audio/scene/workshop-ambience.wav', sig, 0.5);
}

// Pit lane: airy bed with compressor whirr and air-gun ticks.
{
  const sig = makeSeamless(mix(highpass(whiteNoise(6, 131), 240), sine(6, (t) => 190 + 24 * Math.sin(2 * Math.PI * 0.4 * t)), 0.05), 0.4);
  for (let i = 0; i < sig.length; i++) sig[i] *= 0.45 + 0.12 * Math.sin((2 * Math.PI * 0.17 * i) / RATE + 1);
  for (let t = 0; t < 3; t++) {
    const gun = envelope(bandpass(whiteNoise(0.16, 140 + t * 9), 1100, 5200), 0.004, 0.14, 2.4);
    mix(sig, gun, 0.2, 1.2 + t * 1.7);
  }
  writeWav('assets/audio/scene/pit-lane-ambience.wav', sig, 0.55);
}

console.log('done - every file above is an original generated work (see docs/AUDIO-CREDITS.md)');
